question:
Co drží theme, když nad touhle komponentou není žádný Provider pro ThemeContext?

```jsx
const ThemeContext = createContext("light");

function Panel() {
  const theme = useContext(ThemeContext);
  return <p>{theme}</p>;
}
```

Co vykreslí Child?

```jsx
const ThemeContext = createContext("light");

function Child() {
  return <p>{useContext(ThemeContext)}</p>;
}

<ThemeContext.Provider value="dark">
  <ThemeContext.Provider value="high-contrast">
    <Child />
  </ThemeContext.Provider>
</ThemeContext.Provider>
```

Co z tohohle dělá custom hook?

```jsx
function useCounter(start) {
  const [n, setN] = useState(start);
  return { n, inc: () => setN(p => p + 1) };
}
```

Na tlačítko se jednou klikne. Co ukáže?

```jsx
function useToggle(init) {
  const [on, setOn] = useState(init);
  return [on, () => setOn(p => !p)];
}

function Panel() {
  const [open, toggle] = useToggle(false);
  return <button onClick={toggle}>{String(open)}</button>;
}
```

